#ifndef APRS_COMPRESS_H_
#define APRS_COMPRESS_H_

#include <stddef.h>
#include <stdint.h>

// Experimental order-3 context-model compression for short APRS packets.
//
// On air:  0x3C 0xFF (0x80 | modelVersion)  <length>  <range-coded bytes>
// <length> is the length of the original (uncompressed) text, 1..255.
// Plain LoRa APRS keeps using 0x3C 0xFF 0x01, so stations that do not know
// this format ignore these packets instead of misreading them.
//
// Everything is integer-only, so every device decodes exactly what was encoded.
// The model tables (AprsCompressModel.cpp) are generated by
// tools/aprs_compress/train_model.py; changing them requires a new version number.

namespace AprsCompress {

    constexpr uint8_t  HEADER_0     = 0x3C;
    constexpr uint8_t  HEADER_1     = 0xFF;
    constexpr uint8_t  VERSION_FLAG = 0x80;     // third header byte = VERSION_FLAG | modelVersion
    constexpr size_t   MAX_TEXT     = 255;

    uint8_t modelVersion();

    // True if the first three bytes of a received frame are a compressed-frame header for the model we hold.
    bool    isCompressedHeader(const uint8_t* frame, size_t len);

    // Encode a text packet (without the 3-byte header) into a complete on-air frame.
    // Returns the frame length, or 0 if it does not fit or is not smaller than 3 + textLen
    // (the caller should then send the plain frame).
    size_t  encodeFrame(const uint8_t* text, size_t textLen, uint8_t* frame, size_t frameCap);

    // Decode a complete on-air frame back to text (without the 3-byte header).
    // Returns the text length, or 0 on error (wrong header, bad length, output too small).
    size_t  decodeFrame(const uint8_t* frame, size_t frameLen, uint8_t* text, size_t textCap);
}

#endif
